int firstMissing(int* nums, int numsSize) {
    int n = numsSize;
    bool* seen = calloc(n + 2, sizeof(bool));
    for (int i = 0; i < n; i++) if (nums[i] >= 1 && nums[i] <= n + 1) seen[nums[i]] = true;
    int k = 1;
    while (seen[k]) k++;
    free(seen);
    return k;
}

